// Check if this is an automated LinkedIn notification vs personal message
const subject = $input.item.json.subject || '';
const snippet = $input.item.json.snippet || '';
const combinedText = (subject + ' ' + snippet).toLowerCase();

// Automated notification patterns
const automatedPatterns = [
  'job alert',
  'you appeared in',
  'people viewed your profile',
  'connection request',
  'invitation to connect',
  'has endorsed you',
  'commented on your post',
  'liked your post',
  'weekly digest',
  'trending in your network'
];

const isAutomated = automatedPatterns.some(pattern => 
  combinedText.includes(pattern)
);

return {
  ....$input.item.json,
  isAutomated: isAutomated,
  needsReply: !isAutomated
};

// Log execution for monitoring
const now = new Date().toISOString();
const result = {
  success: true,
  agent: 'linkedin',
  messageId: $('Workflow Input').item.json.messageId,
  timestamp: now,
  wasAutomated: $('Check if Automated').item.json.isAutomated,
  replySent: $('Check if Automated').item.json.needsReply,
  responseLength: $json.output?.length || 0
};

return result;

// No reply needed for automated notifications
const now = new Date().toISOString();
const result = {
  success: true,
  agent: 'linkedin',
  messageId: $('Workflow Input').item.json.messageId,
  timestamp: now,
  wasAutomated: true,
  replySent: false,
  action: 'archived_notification'
};

return result;
